// verifyImageCaptcha gate: if (!captchas[0] || answer===...) next()
const captchas=[]; const reqBody={answer:'wrong'};
const bypass = !captchas[0] || reqBody.answer===captchas[0]?.answer;
console.log(bypass ? '[POC_PROVEN] empty captcha set bypasses check' : 'blocked');

// shipped checkData compares removed against added, so removal-only diffs are missed
const fileData={a:{added:[1],removed:[2]}}; const data={a:{added:[1],removed:[99]}};
// shipped: fileData[a].added vs data[a].added (both [1]) => lengths equal, values equal => no flag
// fixed would compare removed [2] vs [99] => flag
const fA=fileData.a.added.sort().toString(); const dA=data.a.added.sort().toString();
const fR=fileData.a.added.sort().toString(); const dR=data.a.added.sort().toString();
console.log(fA===dA && fR===dR ? '[POC_PROVEN] removal diff ignored' : 'flagged');
